.slider__container {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  gap: var(--padding-s);
  width: 100%;
  height: 100%;

  .slides {
    position: relative;
    width: 100%;
    height: 100%;
    min-height: 0;
    display: block;
    overflow: hidden;
    isolation: isolate;

    .slide {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      justify-items: center;
      align-items: center;
      place-items: center;
      display: grid;
