:root {
  font-family: Inter, Helvetica, Arial, sans-serif;
  font-weight: 300;
  font-size: 16px;
  color-scheme: light dark;

  //variables
  --primary-color: #f5f1e8;
  --secondary-color: #1a1816;
  --muted-color: #6e6a64;
  --accent-color: #3f6b5b;
  --primary-color-rgb: 245, 241, 232;
  --secondary-color-rgb: 26, 24, 22;
  --svg-perimeter: 2rem;
  --header-height: 8em;
  --padding-s: 0.5rem;
  --padding-m: 1rem;
  --padding-l: 2rem;
  --m: 4rem;
  --scroll-bar-offset: 17px;
}

