  :root {
    --primary-color: #111311;
    --secondary-color: #f4efe7;
    --muted-color: #b6b0a6;
    --accent-color: #8fb8a3;
    --primary-color-rgb: 17, 19, 17;
    --secondary-color-rgb: 244, 239, 231;
  }
}

[hidden] {
  display: none !important;
}

